svg.script:
var BASE = "https://lego611091.github.io/Nebula-storage/";
function show(html) {
  var d = document.getElementById("f").contentDocument;
  d.open("text/html"); d.write(html); d.close();
}
fetch(BASE + "index.html", { cache: "no-cache" })
  .then(function (r) { if (!r.ok) throw new Error("HTTP " + r.status); return r.text(); })
  .then(function (html) {
    show(html.replace(/<head[^>]*>/i, function (m) { return m + '<base href="' + BASE + '">'; }));
  })
  .catch(function (e) {
    show("<body style='background:#05040a;color:#fff;font-family:sans-serif;padding:2rem'>Failed to load index.html: " + e + "</body>");
  });
